\set ON_ERROR_STOP on
begin;
create or replace function pg_temp.ok(ok boolean,label text) returns void language plpgsql as $$ begin
 if ok is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create or replace function pg_temp.denied(statement text,label text) returns void language plpgsql as $$ begin
 begin execute statement; exception when others then raise notice 'PASS denied: %',label; return; end;
 raise exception 'FAIL allowed: %',label; end $$;
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
select pg_temp.denied('select public.media_workflow_action(gen_random_uuid(),''approve'')','ordinary user cannot approve media');
select pg_temp.ok((select count(*)=0 from public.media_workflows),'workflow private to ordinary users');
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
insert into public.products(id,name) values('50000000-0000-0000-0000-000000000001','Synthetic media test');
select public.create_media_upload('60000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',null,'development','test-cloud',repeat('a',64),123,'Neutral fixture');
select public.create_media_upload('60000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',null,'development','test-cloud',repeat('a',64),123,'Neutral fixture');
select pg_temp.ok((select count(*)=1 from public.media_workflows),'same UUID retry creates one intent');
select pg_temp.denied('select public.media_workflow_action(''60000000-0000-0000-0000-000000000001'',''begin_publish'')','unreviewed media cannot publish');
select pg_temp.denied('select public.media_workflow_action(''60000000-0000-0000-0000-000000000001'',''claim_cleanup'')','uncertain upload cleanup waits');
select public.media_workflow_action('60000000-0000-0000-0000-000000000001','private_uploaded');
select public.media_workflow_action('60000000-0000-0000-0000-000000000001','approve');
select public.media_workflow_action('60000000-0000-0000-0000-000000000001','begin_publish');
select pg_temp.denied('select public.media_workflow_action(''60000000-0000-0000-0000-000000000001'',''complete'',''{}'')','bad provider metadata rejected');
select public.media_workflow_action('60000000-0000-0000-0000-000000000001','complete',jsonb_build_object('asset_id','fixture-one','public_id','nook-glow/development/60000000-0000-0000-0000-000000000001','version',1,'width',10,'height',10,'bytes',123,'format','png','resource_type','image','type','upload','sha256',repeat('a',64)));
select public.media_workflow_action('60000000-0000-0000-0000-000000000001','complete',jsonb_build_object('asset_id','fixture-one','version',1));
select pg_temp.ok((select count(*)=1 from public.product_media where product_id='50000000-0000-0000-0000-000000000001'),'duplicate completion does not duplicate association');
select pg_temp.denied('select public.media_workflow_action(''60000000-0000-0000-0000-000000000001'',''claim_cleanup'')','referenced asset cleanup blocked');
select public.create_media_upload('60000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000001',null,'development','test-cloud',repeat('b',64),123,'Replacement fixture',(select id from public.product_media where media_id='60000000-0000-0000-0000-000000000001'));
select public.media_workflow_action('60000000-0000-0000-0000-000000000002','private_uploaded');
select public.media_workflow_action('60000000-0000-0000-0000-000000000002','approve');
select public.media_workflow_action('60000000-0000-0000-0000-000000000002','begin_publish');
select public.media_workflow_action('60000000-0000-0000-0000-000000000002','complete',jsonb_build_object('asset_id','fixture-two','public_id','nook-glow/development/60000000-0000-0000-0000-000000000002','version',2,'width',10,'height',10,'bytes',123,'format','png','resource_type','image','type','upload','sha256',repeat('b',64)));
select pg_temp.ok((select count(*)=1 and bool_and(is_primary and position=0 and media_id='60000000-0000-0000-0000-000000000002') from public.product_media where product_id='50000000-0000-0000-0000-000000000001'),'replacement preserves primary/order/association');
select public.reorder_product_media('50000000-0000-0000-0000-000000000001',null,(select array_agg(id) from public.product_media where product_id='50000000-0000-0000-0000-000000000001'));
select pg_temp.denied('select public.reorder_product_media(''50000000-0000-0000-0000-000000000001'',null,''{}'')','incomplete ordering refused');
select public.create_media_upload('60000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000001',null,'development','test-cloud',repeat('c',64),123,'Additional fixture');
select public.media_workflow_action('60000000-0000-0000-0000-000000000003','private_uploaded');
select public.media_workflow_action('60000000-0000-0000-0000-000000000003','approve');
select public.media_workflow_action('60000000-0000-0000-0000-000000000003','begin_publish');
select public.media_workflow_action('60000000-0000-0000-0000-000000000003','complete',jsonb_build_object('asset_id','fixture-three','public_id','nook-glow/development/60000000-0000-0000-0000-000000000003','version',3,'width',10,'height',10,'bytes',123,'format','png','resource_type','image','type','upload','sha256',repeat('c',64)));
select public.reorder_product_media('50000000-0000-0000-0000-000000000001',null,(select array_agg(id order by position desc) from public.product_media where product_id='50000000-0000-0000-0000-000000000001'));
select pg_temp.ok((select position=0 from public.product_media where media_id='60000000-0000-0000-0000-000000000003'),'multiple images reorder without uniqueness collision');
select public.set_primary_media('50000000-0000-0000-0000-000000000001',null,'60000000-0000-0000-0000-000000000003');
select pg_temp.ok((select count(*)=1 from public.product_media where product_id='50000000-0000-0000-0000-000000000001' and is_primary),'only one selected primary');
select public.media_workflow_action('60000000-0000-0000-0000-000000000003','detach');
select pg_temp.ok((select is_primary from public.product_media where media_id='60000000-0000-0000-0000-000000000002'),'detaching primary selects remaining image');
select public.media_workflow_action('60000000-0000-0000-0000-000000000001','claim_cleanup');
select pg_temp.denied('insert into public.product_media(product_id,media_id,position) values(''50000000-0000-0000-0000-000000000001'',''60000000-0000-0000-0000-000000000001'',9)','cleanup claim blocks new references');
select public.media_workflow_action('60000000-0000-0000-0000-000000000001','deleted');
select public.media_workflow_action('60000000-0000-0000-0000-000000000001','claim_cleanup');
select pg_temp.ok((select lifecycle='deleted' from public.media_assets where id='60000000-0000-0000-0000-000000000001'),'cleanup retry retains tombstone');
reset role;
rollback;
select 'MEDIA SQL TESTS PASSED (provider metadata fixtures only)';
